__NUXT_JSONP__("/finanzas-publicas/noticias/el_aumento_del_precio_del_petroleo_no_beneficiara_a_mexico", (function(a,b,c,d,e,f){return {data:[{post:{slug:"el_aumento_del_precio_del_petroleo_no_beneficiara_a_mexico",title:"El aumento del precio del petróleo no beneficiará a México",date:"2026-03-09T19:14:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F4f3c1d97-a17d-4d4d-a0a4-bc5fc6a7491a\u002F","img-alt":"PEMEX",autor:"Sergio Martínez, Energía a Debate",link:"https:\u002F\u002Fenergiaadebate.com\u002Fel-aumento-del-precio-del-petroleo-no-beneficiara-a-mexico\u002F",category:"finanzas-publicas",extracto:"Liliana Alvarado, directora general de Ethos, señaló que el precio del petróleo se había presupuestado en 54.9 dólares por barril, dentro de los criterios generales de política económica para 2026, un nivel muy por debajo de los precios actuales del petróleo, apuntó.",toc:[],body:{type:"root",children:[{type:c,tag:d,props:{},children:[{type:a,value:"Con los recientes ataques contra Irán, como parte del conflicto entre Estados Unidos, Israel y la nación iraní, se observa un choque petrolero que ha provocado un incremento en los precios internacionales del energético."}]},{type:a,value:b},{type:c,tag:d,props:{},children:[{type:a,value:"Este crecimiento, se estima, llegará también al precio de la Mezcla Mexicana; sin embargo, expertos coinciden en que este aumento podría no beneficiar al país."}]},{type:a,value:b},{type:c,tag:d,props:{},children:[{type:a,value:"Durante la presentación del análisis “Navegando las Finanzas Públicas de 2025”, por parte de México Evalúa, analistas explicaron el efecto que tendrá el aumento de los precios del petróleo en México."}]},{type:a,value:b},{type:c,tag:e,props:{},children:[{type:a,value:b},{type:c,tag:d,props:{},children:[{type:a,value:"“Sin duda el choque petrolero es la parte más relevante; la mezcla mexicana al cierre del viernes cotizaba alrededor de 82 dólares por barril, con estas referencias cercanas a los 100 dólares del Brent y WTI. Lo más probable es que hoy, al cierre de la jornada… veremos una mezcla más cerca de los 90 dólares por barril”, estimó Víctor Gómez Ayala, Economista en Jefe de Finamex."}]},{type:a,value:b}]},{type:a,value:b},{type:c,tag:d,props:{},children:[{type:a,value:"Por su parte, Liliana Alvarado, directora general de Ethos, señaló que el precio del petróleo se había presupuestado en 54.9 dólares por barril, dentro de los criterios generales de política económica para 2026, un nivel muy por debajo de los precios actuales del petróleo, apuntó."}]},{type:a,value:b},{type:c,tag:e,props:{},children:[{type:a,value:b},{type:c,tag:d,props:{},children:[{type:a,value:"“El día de hoy amanecimos con precios del petróleo de 119 por barril en Brent y WTI. Esto significa una pérdida de recursos para el gobierno porque, recordemos, tenemos el subsidio a las gasolinas”, añadió."}]},{type:a,value:b}]},{type:a,value:b},{type:c,tag:d,props:{},children:[{type:a,value:"Recordó que el precio fijo de la gasolina, establecido en 24 pesos por litro, implicaría  que el gobierno tendría que absorber parte del aumento en el precio del petróleo, lo que resultaría en una menor recaudación del Impuesto Especial sobre Producción y Servicios (IEPS)."}]},{type:a,value:b},{type:c,tag:d,props:{},children:[{type:a,value:"En cuanto al precio de las referencias de gasolina, se tienen que analizar tres puntos, el primero es un precio del petróleo considerablemente más alto, en segundo lugar el tipo de cambio y finalmente el margen de refinación."}]},{type:a,value:b},{type:c,tag:e,props:{},children:[{type:a,value:b},{type:c,tag:d,props:{},children:[{type:a,value:"“Esta combinación es relevante porque reduce la cuota sobre la que se puede recaudar el IEPS por gasolinas por parte del Gobierno Federal”, aclaró Victor Gómez."}]},{type:a,value:b}]},{type:a,value:b},{type:c,tag:d,props:{},children:[{type:a,value:"En su oportunidad, Mariana Campos, titular de México Evalúa, señaló que el año pasado se realizó la reforma para el nuevo Derecho Petrolero del Bienestar, que estableció una nueva tasa fija de 30 por ciento sobre la producción de petróleo, con la cual el gobierno ya no recauda ingresos por los impuestos de Pemex."}]},{type:a,value:b},{type:c,tag:d,props:{},children:[{type:a,value:"Esto, explicó, significa que el aumento del precio del petróleo no se traducirá en mayores ingresos para el gobierno."}]},{type:a,value:b},{type:c,tag:e,props:{},children:[{type:a,value:b},{type:c,tag:d,props:{},children:[{type:a,value:"“Ahora es más difícil que los altos precios del petróleo vayan a beneficiar el presupuesto federal, porque de entrada el gobierno ya recibe menos por la venta de crudo”, evidenció."}]},{type:a,value:b}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Fel_aumento_del_precio_del_petroleo_no_beneficiara_a_mexico",extension:".md",createdAt:f,updatedAt:f}}],fetch:{},mutations:[]}}("text","\n","element","p","blockquote","2026-07-19T00:56:17.217Z")));